package blockbranch.realistic;
/** Cheap pre-change transects: report the field that causes quantized coastal flats. */
public final class SandyCoastDiagnostic {
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var shape=new TerrainShape(seed);var d=new DrainageNetwork(shape,seed);var c=new ClimateField(seed);var candidate=new DrainageNetwork(shape,seed,true,true);for(boolean snow:new boolean[]{false,true}){var scene=CoastalBeachScenes.review(seed,snow);var p=scene==null?blockbranch.realistic.CoastalBeachFixtures.fixture(d,seed,snow):new CoastalBeach.Point(scene.x(),scene.z());var f=CoastalLandforms.frame(seed,shape,p.x(),p.z());int min=99999,max=-99999,flat=0,newMin=99999,newMax=-99999,newFlat=0,changed=0;for(int z=p.z()-128;z<=p.z()+128;z+=8)for(int x=p.x()-128;x<=p.x()+128;x+=8){var s=d.sample(x,z);min=Math.min(min,s.height());max=Math.max(max,s.height());if(s.height()==63)flat++;var n=candidate.sample(x,z);newMin=Math.min(newMin,n.height());newMax=Math.max(newMax,n.height());if(n.height()==63)newFlat++;if(n.height()!=s.height())changed++;if(n.height()-s.height()<0||n.height()-s.height()>4||n.basin()!=s.basin()||n.closed()!=s.closed()||n.regionalHeight()!=s.regionalHeight()||n.regionalWaterLevel()!=s.regionalWaterLevel())throw new AssertionError("Bounded coast and macroclimate preservation");}double gx=(shape.continuousHeight(p.x()+32,p.z())-shape.continuousHeight(p.x()-32,p.z()))/64,gz=(shape.continuousHeight(p.x(),p.z()+32)-shape.continuousHeight(p.x(),p.z()-32))/64; double distance=(shape.continuousHeight(p.x(),p.z())-63)/Math.hypot(gx,gz);System.out.println("SANDY_DIAG seed="+seed+" snow="+snow+" p="+p+" rawDistance="+distance+" rawSlope="+Math.hypot(gx,gz)+" frame="+f+" region="+min+".."+max+" y63="+flat+"/1089 new="+newMin+".."+newMax+" newY63="+newFlat+" changed="+changed+" candidateBiome="+CoastalBeach.contains(p.x(),p.z(),candidate,c,snow));if(scene!=null){
 double lo=-256,hi=256;for(int i=0;i<14;i++){double mid=(lo+hi)/2;if(CoastalBeachScenes.ocean(candidate,scene.x()+scene.seaX()*mid,scene.z()+scene.seaZ()*mid))hi=mid;else lo=mid;}
 var rows=new StringBuilder("distance,x,z,h,water,band,slope,beach\n");
 for(int n=0;n<=256;n+=4){int x=(int)Math.round(scene.x()+scene.seaX()*(hi-n)),z=(int)Math.round(scene.z()+scene.seaZ()*(hi-n));var a=candidate.sample(x,z);double slope=Math.hypot((candidate.sample(x+32,z).height()-candidate.sample(x-32,z).height())/64.,(candidate.sample(x,z+32).height()-candidate.sample(x,z-32).height())/64.);rows.append(n+","+x+","+z+","+a.height()+","+a.waterLevel()+","+a.sandyBackshore()+","+slope+","+CoastalBeach.surfaceContains(x,z,candidate,c,snow)+"\n");}
 try{java.nio.file.Files.writeString(java.nio.file.Path.of("/workspace/scratch/sandy-transect-"+snow+".csv"),rows);}catch(Exception e){throw new RuntimeException(e);}
 try{System.out.println("SANDY_NEW_TRANSECT "+CoastalBeachScenes.transect(scene,candidate,c,0));}catch(AssertionError e){System.out.println("SANDY_TRANSECT_REJECTED "+e.getMessage());}
 }}}}
}
